  df-bnj17 $a |- ( ( ph /\ ps /\ ch /\ th ) <-> ( ( ph /\ ps /\ ch ) /\ th ) )
      $.

$( -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=- $)

$( Function meta-constant representing the function giving:
   the class of all elements of ` A ` that are "smaller" than ` X ` according
   to ` R `. $)

  $c _pred $.

  $( Extend class notation with the function giving: the class of all elements
     of ` A ` that are "smaller" than ` X ` according to ` R ` .
     (New usage is discouraged.) $)
  c-bnj14 $a class _pred ( X , A , R ) $.

  ${
    $d X y $.  $d A y $.  $d R y $.
    $( Define the function giving: the class of all elements of ` A ` that are
       "smaller" than ` X ` according to ` R ` .  (Contributed by Jonathan
       Ben-Naim, 3-Jun-2011.)  (New usage is discouraged.) $)
    df-bnj14 $a |- _pred ( X , A , R ) = { y e. A | y R X } $.
  $}

$( -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=- $)

$( Predicate meta-constant representing the following predicate:
   ` R ` is set-like on ` A `. $)

  $c _Se $.

  $( Extend wff notation with the following predicate: ` R ` is set-like on
     ` A ` .  (New usage is discouraged.) $)
  w-bnj13 $a wff R _Se A $.

  ${
    $d R x $.  $d A x $.
    $( Define the following predicate: ` R ` is set-like on ` A ` .
       (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
       (New usage is discouraged.) $)
    df-bnj13 $a |- ( R _Se A <-> A. x e. A _pred ( x , A , R ) e. _V ) $.
  $}

$( -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=- $)

$( Predicate meta-constant representing the following predicate:
   ` R ` is both well-founded and set-like on ` A `. $)

  $c _FrSe $.

  $( Extend wff notation with the following predicate: ` R ` is both
     well-founded and set-like on ` A ` .  (New usage is discouraged.) $)
  w-bnj15 $a wff R _FrSe A $.

  $( Define the following predicate: ` R ` is both well-founded and set-like on
     ` A ` .  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (New usage is discouraged.) $)
  df-bnj15 $a |- ( R _FrSe A <-> ( R Fr A /\ R _Se A ) ) $.

$( -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=- $)

$( Function meta-constant representing the function giving:
   the transitive closure of ` X ` in ` A ` by ` R `. $)

  $c _trCl $.

  $( Extend class notation with the function giving: the transitive closure of
     ` X ` in ` A ` by ` R ` .  (New usage is discouraged.) $)
  c-bnj18 $a class _trCl ( X , A , R ) $.

  ${
    $d X f n i y $.  $d A f n i y $.  $d R f n i y $.
    $( Define the function giving: the transitive closure of ` X ` in ` A ` by
       ` R ` .  This definition has been designed for facilitating verification
       that it is eliminable and that the $d restrictions are sound and
       complete.  For a more readable definition see ~ bnj882 .  (Contributed
       by Jonathan Ben-Naim, 3-Jun-2011.)  (New usage is discouraged.) $)
    df-bnj18 $a |- _trCl ( X , A , R )
      = U_ f e. { f | E. n e. ( _om \ { (/) } ) ( f Fn n /\ ( f ` (/) )
       = _pred ( X , A , R ) /\ A. i e. _om ( suc i e. n -> ( f ` suc i )
       = U_ y e. ( f ` i ) _pred ( y , A , R ) ) ) } U_ i e. dom f ( f ` i ) $.
  $}

$( -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=- $)

$( Predicate meta-constant representing the following predicate:
   ` B ` is transitive for ` A ` and ` R `. $)

  $c _TrFo $.

  $( Extend wff notation with the following predicate: ` B ` is transitive for
     ` A ` and ` R ` .  (New usage is discouraged.) $)
  w-bnj19 $a wff _TrFo ( B , A , R ) $.

  ${
    $d B x $.  $d A x $.  $d R x $.
    $( Define the following predicate: ` B ` is transitive for ` A ` and
       ` R ` .  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
       (New usage is discouraged.) $)
    df-bnj19 $a |- ( _TrFo ( B , A , R ) <-> A. x e. B _pred ( x , A , R ) C_ B
        ) $.
  $}


$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  First-order logic and set theory
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (Proof shortened by Andrew Salmon, 14-Jun-2011.)
     (New usage is discouraged.) $)
  bnj170 $p |- ( ( ph /\ ps /\ ch ) <-> ( ( ps /\ ch ) /\ ph ) ) $=
    ( w3a wa 3anrot df-3an bitri ) ABCDBCADBCEAEABCFBCAGH $.

  ${
    bnj240.1 $e |- ( ps -> ps' ) $.
    bnj240.2 $e |- ( ch -> ch' ) $.
    $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
       (New usage is discouraged.) $)
    bnj240 $p |- ( ( ph /\ ps /\ ch ) -> ( ps' /\ ch' ) ) $=
      ( wa w3a 3ad2ant1 3ad2ant2 jca 3comr ) BCADEHBCAIDEBCDAFJCBEAGKLM $.
  $}

  $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (New usage is discouraged.) $)
  bnj248 $p |- ( ( ph /\ ps /\ ch /\ th ) <-> ( ( ( ph /\ ps ) /\ ch ) /\ th
      ) ) $=
    ( w-bnj17 w3a wa df-bnj17 df-3an anbi1i bitri ) ABCDEABCFZDGABGCGZDGABCDHLM
    DABCIJK $.

  $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (New usage is discouraged.) $)
  bnj250 $p |- ( ( ph /\ ps /\ ch /\ th ) <-> ( ph /\ ( ( ps /\ ch ) /\ th )
      ) ) $=
    ( w-bnj17 w3a wa df-bnj17 3anass anbi1i anass 3bitri ) ABCDEABCFZDGABCGZGZD
    GANDGGABCDHMODABCIJANDKL $.

  $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (New usage is discouraged.) $)
  bnj251 $p |- ( ( ph /\ ps /\ ch /\ th ) <-> ( ph /\ ( ps /\ ( ch /\ th ) )
      ) ) $=
    ( w-bnj17 wa bnj250 anass anbi2i bitri ) ABCDEABCFDFZFABCDFFZFABCDGKLABCDHI
    J $.

  $( ` /\ ` -manipulation.  (Contributed by Jonathan Ben-Naim, 3-Jun-2011.)
     (New usage is discouraged.) $)
